package in.tucor.api.config;
import in.tucor.api.auth.*; import jakarta.servlet.*; import jakarta.servlet.http.*; import org.springframework.beans.factory.annotation.Value; import org.springframework.context.annotation.*; import org.springframework.security.authentication.UsernamePasswordAuthenticationToken; import org.springframework.security.config.annotation.web.builders.HttpSecurity; import org.springframework.security.config.http.SessionCreationPolicy; import org.springframework.security.core.authority.SimpleGrantedAuthority; import org.springframework.http.HttpMethod; import org.springframework.security.crypto.bcrypt.BCryptPasswordEncoder; import org.springframework.security.crypto.password.PasswordEncoder; import org.springframework.security.web.SecurityFilterChain; import org.springframework.security.web.authentication.UsernamePasswordAuthenticationFilter; import org.springframework.web.cors.*; import java.io.IOException; import java.util.*;
@Configuration public class SecurityConfig {@Value("${tucor.cors-origins:http://localhost:4028}") private String corsOrigins;@Bean PasswordEncoder encoder(){return new BCryptPasswordEncoder();}
@Bean SecurityFilterChain chain(HttpSecurity h,JwtService jwt,UserRepository users) throws Exception {h.csrf(c->c.disable()).cors(cors->cors.configurationSource(corsConfigurationSource())).sessionManagement(s->s.sessionCreationPolicy(SessionCreationPolicy.STATELESS)).authorizeHttpRequests(a->a.requestMatchers(HttpMethod.OPTIONS,"/**").permitAll().requestMatchers("/api/buyer/**").hasRole("BUYER").requestMatchers("/api/seller/**").hasRole("SELLER").requestMatchers("/api/admin/**").hasRole("ADMIN").requestMatchers("/api/auth/register","/api/auth/login","/api/auth/refresh","/api/auth/logout","/api/auth/forgot-password","/api/auth/reset-password","/api/auth/verify-email","/api/auth/resend-verification","/actuator/health").permitAll().anyRequest().authenticated()).addFilterBefore(new JwtFilter(jwt,users),UsernamePasswordAuthenticationFilter.class);return h.build();}
@Bean CorsConfigurationSource corsConfigurationSource(){CorsConfiguration c=new CorsConfiguration();c.setAllowedOriginPatterns(Arrays.stream(corsOrigins.split(",")).map(String::trim).filter(x->!x.isBlank()).toList());c.setAllowedMethods(List.of("GET","POST","PUT","PATCH","DELETE","OPTIONS"));c.setAllowedHeaders(List.of("Content-Type","Authorization","Accept","Origin","X-Requested-With"));c.setAllowCredentials(true);c.setMaxAge(3600L);UrlBasedCorsConfigurationSource s=new UrlBasedCorsConfigurationSource();s.registerCorsConfiguration("/**",c);return s;}
static class JwtFilter extends org.springframework.web.filter.OncePerRequestFilter {private final JwtService jwt;private final UserRepository users;JwtFilter(JwtService jwt,UserRepository users){this.jwt=jwt;this.users=users;}protected void doFilterInternal(HttpServletRequest r,HttpServletResponse p,FilterChain c)throws ServletException,IOException{String h=r.getHeader("Authorization");if(h!=null&&h.startsWith("Bearer ")){try{var cl=jwt.parse(h.substring(7));User user=users.findById(UUID.fromString(cl.getSubject())).orElseThrow();String role=cl.get("role",String.class);boolean registrationUpload="/api/auth/registration-documents".equals(r.getRequestURI());boolean enabled=!List.of("SUSPENDED","REJECTED").contains(user.status);if(enabled&&(user.emailVerified||registrationUpload)&&user.role.name().equals(role)){var auth=new UsernamePasswordAuthenticationToken(cl.getSubject(),null,List.of(new SimpleGrantedAuthority("ROLE_"+role)));org.springframework.security.core.context.SecurityContextHolder.getContext().setAuthentication(auth);}}catch(Exception ignored){}}c.doFilter(r,p);}}}
